-- Step 6 (21 Nov, docs/database-plan.md, the food and check-in items' bounded slices): what the coach-wide reads of the
-- food diary and the check-in figures need to fetch only what they show (app/lib/food/slices.ts, app/lib/checkins/slices.ts,
-- the predicates in app/lib/pg/feedSlices.ts): the real instant beside calorie_logs.logged_at and check_in_notes.created_at
-- (as 0016 put one beside food_entries.logged_at), each figure's client (metric_entries.def_client_id, its metric's as
-- memory holds the definitions: one probe a client, not one a metric), and the indexes the slices read. Nothing the app
-- reads changes: the columns are filled by the writer (pg/schema.ts DERIVED) and put right at boot (store.ts
-- derivedStale), never loaded back. The columns are filled before the indexes are built. Every statement can run twice.
ALTER TABLE "calorie_logs" ADD COLUMN IF NOT EXISTS "logged_at_tz" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "check_in_notes" ADD COLUMN IF NOT EXISTS "created_at_tz" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "metric_entries" ADD COLUMN IF NOT EXISTS "def_client_id" integer;--> statement-breakpoint
UPDATE "calorie_logs" SET "logged_at_tz" = norcoach_stamp("logged_at") WHERE "logged_at_tz" IS DISTINCT FROM norcoach_stamp("logged_at");--> statement-breakpoint
UPDATE "check_in_notes" SET "created_at_tz" = norcoach_stamp("created_at") WHERE "created_at_tz" IS DISTINCT FROM norcoach_stamp("created_at");--> statement-breakpoint
UPDATE "metric_entries" e SET "def_client_id" = d."client_id" FROM "metric_definitions" d WHERE d."id" = e."metric_definition_id" AND e."def_client_id" IS DISTINCT FROM d."client_id";--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "calorie_logs_client_tz_idx" ON "calorie_logs" USING btree ("client_id","logged_at_tz","id") WHERE logged_at_tz IS NOT NULL AND ((extra ->> 'source') IS DISTINCT FROM 'health');--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "calorie_logs_odd_idx" ON "calorie_logs" USING btree ("client_id","date") WHERE (((extra ->> 'source') IS DISTINCT FROM 'health') AND ((NOT (COALESCE(date, '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')) OR (extra ? 'logged_at') OR ((logged_at IS NOT NULL AND logged_at <> '') AND (logged_at_tz IS NULL OR NOT (logged_at ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$' OR logged_at ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,3})?(Z|[+-][0-9]{2}:[0-9]{2})$')))));--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "calorie_logs_blank_idx" ON "calorie_logs" USING btree ("client_id",(date COLLATE "C"),"id") WHERE ((extra ->> 'source') IS DISTINCT FROM 'health') AND ((logged_at IS NULL OR logged_at = '') AND NOT COALESCE(extra ? 'logged_at', false));--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "calorie_logs_typed_idx" ON "calorie_logs" USING btree ("client_id","id") WHERE ((extra ->> 'source') IS DISTINCT FROM 'health');--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "check_in_notes_client_tz_idx" ON "check_in_notes" USING btree ("client_id","created_at_tz","id") WHERE created_at_tz IS NOT NULL;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "check_in_notes_client_period_idx" ON "check_in_notes" USING btree ("client_id",(period COLLATE "C"),"id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "check_in_notes_odd_idx" ON "check_in_notes" USING btree ("client_id","id") WHERE ((NOT (COALESCE(period, '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')) OR (extra ? 'created_at') OR ((created_at IS NOT NULL AND created_at <> '') AND (created_at_tz IS NULL OR NOT (created_at ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$' OR created_at ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,3})?(Z|[+-][0-9]{2}:[0-9]{2})$'))));--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "food_entries_client_tz_idx" ON "food_entries" USING btree ("client_id","logged_at_tz","id") WHERE logged_at_tz IS NOT NULL;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "food_entries_odd_idx" ON "food_entries" USING btree ("client_id","date") WHERE ((NOT (COALESCE(date, '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')) OR (extra ? 'logged_at') OR ((logged_at IS NOT NULL AND logged_at <> '') AND (logged_at_tz IS NULL OR NOT (logged_at ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$' OR logged_at ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,3})?(Z|[+-][0-9]{2}:[0-9]{2})$'))));--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "food_entries_blank_idx" ON "food_entries" USING btree ("client_id",(date COLLATE "C"),"id") WHERE ((logged_at IS NULL OR logged_at = '') AND NOT COALESCE(extra ? 'logged_at', false));--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "meal_photos_nolook_idx" ON "meal_photos" USING btree ("id") WHERE (NOT COALESCE(jsonb_typeof(extra -> 'thumb') = 'string' AND (extra ->> 'thumb') <> '', false));--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "metric_entries_client_tz_idx" ON "metric_entries" USING btree ("def_client_id","logged_at_tz","id") WHERE logged_at_tz IS NOT NULL AND (value IS NOT NULL AND ((extra ->> 'source') IS DISTINCT FROM 'health'));--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "metric_entries_client_period_idx" ON "metric_entries" USING btree ("def_client_id",(period COLLATE "C"),"id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "metric_entries_client_odd_idx" ON "metric_entries" USING btree ("def_client_id","id") WHERE ((value IS NOT NULL OR (extra ? 'value')) AND ((extra ->> 'source') IS DISTINCT FROM 'health') AND ((extra ? 'value') OR (NOT (COALESCE(period, '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')) OR (extra ? 'logged_at') OR ((logged_at IS NOT NULL AND logged_at <> '') AND (logged_at_tz IS NULL OR NOT (logged_at ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$' OR logged_at ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,3})?(Z|[+-][0-9]{2}:[0-9]{2})$')))));--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "metric_entries_client_blank_idx" ON "metric_entries" USING btree ("def_client_id",(period COLLATE "C"),"id") WHERE (value IS NOT NULL AND ((extra ->> 'source') IS DISTINCT FROM 'health')) AND ((logged_at IS NULL OR logged_at = '') AND NOT COALESCE(extra ? 'logged_at', false));--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "saved_meals_nolook_idx" ON "saved_meals" USING btree ("id") WHERE ((extra -> 'picture') IS NOT NULL AND jsonb_typeof(extra -> 'picture') <> 'null' AND NOT COALESCE(jsonb_typeof(extra -> 'picture_thumb') = 'string' AND (extra ->> 'picture_thumb') <> '', false));
